  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Clauses, Phrases, Colons and Semicolons$j$, $j${"readings": [], "body": "A phrase is a group of words without a subject and verb together. A clause has a subject and a verb. An independent clause stands alone; a dependent clause cannot.\n\nA semicolon joins two closely related independent clauses. A colon introduces a list, quotation or explanation after a complete sentence.\n\nYour task: write two sentences using a semicolon, two using a colon and one that uses a dependent clause correctly.\n\nFlorida standards: ELA.9.C.3.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.9.C.3.1", "script": "We end our course with two tools that make your sentences stronger and more varied. They are clauses and the punctuation that joins them.\n\nLet us begin with definitions. A phrase is a group of related words that does not have both a subject and a verb. Examples are in the morning, running down the hall and to the store. A clause is a group of words that has both a subject and a verb. There are two types. An independent clause can stand alone as a complete sentence: the students studied. A dependent clause has a subject and a verb but cannot stand alone, because it begins with a word like because, although, when or if. Although the students studied is not a complete sentence. It leaves us waiting.\n\nWhen you attach a dependent clause to an independent clause, you create a complex sentence. Although the students studied, they felt nervous. Note the comma after an introductory dependent clause.\n\nNow the semicolon. A semicolon joins two independent clauses that are closely related in meaning, without a conjunction. The students studied hard; they passed the test. Each side could be a sentence alone, but the semicolon shows a close connection. Also use a semicolon before a conjunctive adverb such as however or therefore: she was tired; however, she kept working.\n\nThen the colon. A colon follows a complete sentence and introduces a list, a quotation or an explanation. For example: Bring three things: a pencil, a notebook and a Bible. Or: He learned one lesson: patience pays. Do not put a colon directly after a verb or a preposition. Write, I need pencils, paper and a ruler, with no colon before the list.\n\nAlso notice the use of the colon in a quotation. In Philippians chapter four, we read: I can do all things through Christ which strengtheneth me.\n\nHere is a quick memory trick. A semicolon is like a soft period: it connects two complete thoughts. A colon is like a door: it opens to what comes next.\n\nYour task today is to write two sentences with semicolons, two with colons and one with a dependent clause used correctly. Then take the four question check and the Unit 6 quiz.\n\nStrong conventions free your ideas to be heard. Finish well. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Clauses, Phrases, Colons and Semicolons$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Literary Analysis Paragraph$j$, $j${"prompt": "Choose \"The Gift of the Magi\" or Luke 15:11 to 32 (KJV). Write one paragraph of 150 to 200 words. State a theme in one sentence. Support it with two pieces of evidence from the text, one about a character and one about the conflict. Name the point of view.", "rubric": "Total 100. Theme is a full statement: 25. Two pieces of text evidence: 30. Explains how the evidence supports the theme: 25. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Literary Analysis Paragraph$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Poetry Analysis$j$, $j${"prompt": "Choose Psalm 1, Psalm 19 or \"The Road Not Taken.\" Write 150 to 200 words explaining the meaning of the poem and how two devices (imagery, sound, simile, metaphor or symbol) help create that meaning. Use at least two quotations.", "rubric": "Total 100. States the meaning of the poem: 25. Names and explains two devices: 30. Uses two quotations correctly: 20. Connects devices to meaning: 15. Clear writing and conventions: 10."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Poetry Analysis$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Summary and Purpose Response$j$, $j${"prompt": "Choose the Gettysburg Address or the Douglass speech. In 150 to 200 words, write (1) a three sentence summary in your own words, (2) the author's purpose and perspective, and (3) two pieces of evidence from the text.", "rubric": "Total 100. Accurate summary in own words: 30. States purpose and perspective: 25. Two pieces of evidence: 25. Clear writing and conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Summary and Purpose Response$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Rhetorical Analysis$j$, $j${"prompt": "Choose Acts 26:1 to 29 or Proverbs 15 (KJV). In 175 to 225 words, state the claim, identify one example of ethos, pathos and logos (or the strongest two for Proverbs), and explain how each helps persuade.", "rubric": "Total 100. Accurate claim: 20. Three appeals identified correctly: 30. Explains the effect of each: 30. Clear writing and conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Rhetorical Analysis$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Expository Essay$j$, $j${"prompt": "Write an expository essay of 400 to 500 words on one of these topics: the value of daily reading, the importance of integrity, or the benefits of community service. Include an introduction with a thesis, three body paragraphs and a conclusion.", "rubric": "Total 100. Clear thesis: 15. Organization and transitions: 20. Evidence and reasoning: 25. Style and word choice: 15. Conventions: 15. Length and format: 10."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Expository Essay$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Vocabulary and Conventions in Use$j$, $j${"prompt": "Write a paragraph of 120 to 160 words about a lesson you learned this year. Include: two words with prefixes or suffixes that you explain, one word chosen for its connotation (explain why), one sentence with a semicolon, one with a colon, and one with a dependent clause. Label each in parentheses after the paragraph.", "rubric": "Total 100. Two word parts explained: 20. Connotation explained: 15. Semicolon, colon and dependent clause correct: 30. Clear paragraph: 20. Conventions: 15."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Vocabulary and Conventions in Use$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Argumentative Essay (500 words or more)$j$, $j${"prompt": "Write an argumentative essay of at least 500 words on this question: Should every student be required to read for twenty minutes every day? Take a clear position. Include an introduction with a hook and thesis, at least three body paragraphs with evidence and reasoning, a counterclaim with a rebuttal, and a conclusion. Use at least one quotation from Scripture (KJV) or from a text read in this course, and use ethos, pathos and logos on purpose.", "rubric": "Total 100. Clear, debatable thesis: 10. Organization and transitions: 15. Evidence from at least two sources and reasoning: 25. Counterclaim and rebuttal: 15. Use of rhetorical appeals: 10. Style and word choice: 10. Conventions: 10. Length of 500 words or more: 5. A score of 70 or better is required to pass. A certified proctor and the 500 word essay requirement apply to Adult Diploma Assessment Program students."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Argumentative Essay (500 words or more)$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Choices That Reveal Character$j$, $j${"prompt": "Think of a character, in a book or in Scripture, whose choice revealed what he or she valued most. Describe the choice, and tell what it shows about the character. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Choices That Reveal Character$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: A Picture That Stays With You$j$, $j${"prompt": "Share a line from a poem or Psalm that creates a picture in your mind. Tell what you see and what feeling it gives you. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: A Picture That Stays With You$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Words That Move People$j$, $j${"prompt": "Tell about a speech, sermon or article that changed how you think. What was the author's purpose, and what did the author do to reach you? Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Words That Move People$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Disagreeing Well$j$, $j${"prompt": "Think about a time you disagreed with someone and handled it well, or wish you had. What would a soft answer have changed? Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Disagreeing Well$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: My Writing Process$j$, $j${"prompt": "Which stage of writing is hardest for you: planning, drafting, revising or editing? Tell why, and share one strategy from this unit that you will try. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: My Writing Process$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: A Word I Want to Own$j$, $j${"prompt": "Pick one new word you learned in this course. Tell where you found it, what it means and a sentence that uses it. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: A Word I Want to Own$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Plot and Conflict$j$, $j${"questions": [{"q": "Which part of the plot is the turning point where everything changes?", "options": ["Resolution", "Exposition", "Climax", "Setting"]}, {"q": "A character fights fear inside himself before making a choice. This is an example of:", "options": ["Internal conflict", "Resolution", "Exposition", "External conflict"]}, {"q": "Which part of the plot introduces the characters and setting?", "options": ["Climax", "Falling action", "Resolution", "Exposition"]}, {"q": "David against Goliath is an example of which conflict?", "options": ["Only a resolution", "Neither", "External, and also internal because David must choose faith over fear", "Only internal"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Plot and Conflict$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,2}'::int[], array[$j$The climax is the turning point of the plot.$j$,$j$A struggle inside the character is internal conflict.$j$,$j$Exposition introduces the characters and setting.$j$,$j$It is external, and David also faces an inner choice between fear and faith.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Plot and Conflict$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Character and Characterization$j$, $j${"questions": [{"q": "An author shows a character is kind by describing him giving away his coat. This is:", "options": ["Direct characterization", "Climax", "Indirect characterization", "Exposition"]}, {"q": "A character who changes during the story is called:", "options": ["Static", "Minor", "Dynamic", "Flat"]}, {"q": "A narrator says, 'Maria was a patient girl.' This is:", "options": ["A metaphor", "Direct characterization", "A theme", "Indirect characterization"]}, {"q": "A complex character with strengths and weaknesses is a:", "options": ["Minor plot", "Round character", "Static setting", "Flat character"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Character and Characterization$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,1,1}'::int[], array[$j$Showing through action is indirect characterization.$j$,$j$A dynamic character changes.$j$,$j$The narrator tells us outright, so it is direct.$j$,$j$Round characters are complex.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Character and Characterization$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Setting and Mood$j$, $j${"questions": [{"q": "Setting includes:", "options": ["Only the place", "The theme", "Both time and place", "Only the time"]}, {"q": "Mood is best described as:", "options": ["The author's opinion", "The main character's name", "The feeling the reader gets", "The plot's climax"]}, {"q": "Which detail most helps create a tense mood?", "options": ["A bright classroom", "A silent road at midnight", "A sunny picnic", "A cheerful song"]}, {"q": "How can setting affect conflict?", "options": ["It cannot", "It only changes the title", "It decides the theme alone", "A storm at sea creates different problems than a quiet kitchen"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Setting and Mood$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,1,3}'::int[], array[$j$Setting is time and place.$j$,$j$Mood is the feeling the text creates in the reader.$j$,$j$A silent road at midnight suggests tension.$j$,$j$Place and time can create or shape the conflict.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Setting and Mood$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Theme and Point of View$j$, $j${"questions": [{"q": "Which is written as a theme?", "options": ["Forgiveness", "Pride can keep us from receiving grace", "Luke fifteen", "The prodigal son"]}, {"q": "A narrator who says 'I' is using:", "options": ["First person", "Third person omniscient", "Third person limited", "Second person"]}, {"q": "A narrator who knows every character's thoughts is:", "options": ["Third person omniscient", "Third person limited", "Static", "First person"]}, {"q": "To prove a theme you should:", "options": ["Guess", "Ignore the ending", "Copy the title", "Use details from the text as evidence"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Theme and Point of View$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,0,3}'::int[], array[$j$A theme is a full statement about life.$j$,$j$First person uses the word I.$j$,$j$That is omniscient.$j$,$j$A theme must be supported by evidence.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Theme and Point of View$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Reading Fiction, Story Elements$j$, $j${"questions": [{"q": "The struggle that drives a plot is called:", "options": ["Conflict", "Diction", "Setting", "Mood"]}, {"q": "Which sequence is in the correct order?", "options": ["Exposition, rising action, climax, falling action, resolution", "Climax, exposition, resolution", "Resolution, climax, exposition", "Rising action, exposition, resolution"]}, {"q": "Telling the reader a character is brave is:", "options": ["Indirect characterization", "Direct characterization", "Setting", "Theme"]}, {"q": "A static character:", "options": ["Changes greatly", "Is always the hero", "Narrates", "Stays the same"]}, {"q": "Mood is:", "options": ["The ending", "The author's attitude", "The point of view", "The feeling the reader gets"]}, {"q": "A good theme is:", "options": ["The title", "One word", "A full statement about life supported by evidence", "The setting"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Reading Fiction, Story Elements$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,1,3,3,2}'::int[], array[$j$Conflict drives the plot.$j$,$j$This is the plot order.$j$,$j$Direct characterization states the trait.$j$,$j$Static characters do not change.$j$,$j$Mood is felt by the reader.$j$,$j$Themes are full statements with evidence.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Reading Fiction, Story Elements$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: How to Read a Poem$j$, $j${"questions": [{"q": "A group of lines in a poem is called a:", "options": ["Stanza", "Plot", "Scene", "Chapter"]}, {"q": "The voice that talks in a poem is the:", "options": ["Speaker", "Author's agent", "Reader", "Setting"]}, {"q": "The first reading of a poem should focus on:", "options": ["Sound, reading aloud", "Grammar mistakes", "The poet's biography", "Memorizing"]}, {"q": "Saying something in one line and echoing it in the next is called:", "options": ["Parallelism", "Dialogue", "Exposition", "Footnote"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: How to Read a Poem$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,0,0}'::int[], array[$j$A stanza is a group of lines.$j$,$j$The speaker is the voice.$j$,$j$Read first for sound.$j$,$j$That is parallelism.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: How to Read a Poem$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Imagery and Sound$j$, $j${"questions": [{"q": "Imagery appeals to:", "options": ["Only rhythm", "The senses", "Only grammar", "Only rhyme"]}, {"q": "Repetition of beginning consonant sounds is:", "options": ["Rhyme", "Alliteration", "Plot", "Assonance"]}, {"q": "The words 'light' and 'night' show:", "options": ["Rhyme", "Theme", "Setting", "Metaphor"]}, {"q": "Which is the strongest image?", "options": ["A crimson rose heavy with rain", "A thing", "A nice day", "Something good"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Imagery and Sound$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,0,0}'::int[], array[$j$Imagery appeals to the senses.$j$,$j$That is alliteration.$j$,$j$They share ending sounds, which is rhyme.$j$,$j$Specific details create strong images.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Imagery and Sound$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Simile, Metaphor and Symbol$j$, $j${"questions": [{"q": "A comparison using 'like' or 'as' is a:", "options": ["Symbol", "Metaphor", "Simile", "Theme"]}, {"q": "'The Lord is my shepherd' is a:", "options": ["Metaphor", "Simile", "Exposition", "Alliteration"]}, {"q": "Giving human qualities to a non human thing is:", "options": ["Rhyme", "Irony", "Symbolism", "Personification"]}, {"q": "A dove standing for peace is a:", "options": ["Plot", "Stanza", "Symbol", "Pronoun"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Simile, Metaphor and Symbol$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,2}'::int[], array[$j$That is a simile.$j$,$j$It says one thing is another, so it is a metaphor.$j$,$j$That is personification.$j$,$j$An object standing for a larger idea is a symbol.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Simile, Metaphor and Symbol$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Reading Psalm 23 as Poetry$j$, $j${"questions": [{"q": "A comparison that continues through many lines is an:", "options": ["Extended metaphor", "Climax", "Alliteration", "Exposition"]}, {"q": "A strong analysis should:", "options": ["Retell the story", "Only list devices", "Avoid quotations", "Connect devices to meaning"]}, {"q": "The shift from 'he' to 'thou' in Psalm 23 shows:", "options": ["A move from description to closeness", "A mistake", "A rhyme scheme", "A change of setting"]}, {"q": "A table prepared in the presence of enemies is an image of:", "options": ["Travel", "Loneliness", "Honor in the middle of threat", "Hunger"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Reading Psalm 23 as Poetry$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,0,2}'::int[], array[$j$That is an extended metaphor.$j$,$j$Always explain the effect.$j$,$j$The speaker moves to speaking directly to God.$j$,$j$It pictures honor and care despite danger.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Reading Psalm 23 as Poetry$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Poetry and Figurative Language$j$, $j${"questions": [{"q": "A group of lines in a poem is a:", "options": ["Stanza", "Thesis", "Scene", "Verse chapter only"]}, {"q": "Language that appeals to the senses is:", "options": ["Plot", "Thesis", "Imagery", "Syntax"]}, {"q": "'Her laugh was music' is a:", "options": ["Personification", "Metaphor", "Simile", "Alliteration"]}, {"q": "'Silver, sweet, singing' shows:", "options": ["Symbol", "Plot", "Rhyme", "Alliteration"]}, {"q": "'The wind whispered' is:", "options": ["Personification", "Setting", "Symbol", "Simile"]}, {"q": "Good poetry analysis connects devices to:", "options": ["Page numbers", "Rhyme only", "Meaning and effect", "The poet's age"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Poetry and Figurative Language$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,1,3,0,2}'::int[], array[$j$A stanza is a group of lines.$j$,$j$That is imagery.$j$,$j$No like or as, so it is a metaphor.$j$,$j$Repeated beginning sounds.$j$,$j$The wind is given a human action.$j$,$j$Always explain meaning and effect.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Poetry and Figurative Language$j$ on conflict (item_id) do nothing;
